import{_ as e,a0 as a,w as r,s as p,I as n,x as i,a1 as o,A as s,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"如何在一个 U 盘上安装多个 Linux 发行版 | LCTT x X-CMD","titleTemplate":false,"description":"如何在一个 U 盘上安装多个 Linux 发行版 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在一个 U 盘上安装多个 Linux 发行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在一个 U 盘上安装多个 Linux 发行版 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20171008 How to Install Multiple Linux Distributions on One USB","title":"如何在一个 U 盘上安装多个 Linux 发行版","tag":"201710","desc":""},"relativePath":"201710/20171008 How to Install Multiple Linux Distributions on One USB.md","filePath":"[post].md"}'),d={name:"201710/20171008 How to Install Multiple Linux Distributions on One USB.md"};function x(m,t,b,U,f,L){const l=a("Link");return r(),p("div",null,[t[19]||(t[19]=n("h1",{id:"如何在一个-u-盘上安装多个-linux-发行版",tabindex:"-1"},[i("如何在一个 U 盘上安装多个 Linux 发行版 "),n("a",{class:"header-anchor",href:"#如何在一个-u-盘上安装多个-linux-发行版","aria-label":"Permalink to “如何在一个 U 盘上安装多个 Linux 发行版”"},"​")],-1)),t[20]||(t[20]=n("blockquote",null,[n("p",null,[i("概要：本教程介绍如何在一个 U 盘上安装多个 Linux 发行版。这样，你可以在单个 U 盘上享受多个"),n("ruby",null,[i("现场版"),n("rt",null,"live")]),i(" Linux 发行版了。")])],-1)),t[21]||(t[21]=n("p",null,"我喜欢通过 U 盘尝试不同的 Linux 发行版。它让我可以在真实的硬件上测试操作系统，而不是虚拟化的环境中。此外，我可以将 USB 插入任何系统（比如 Windows 系统），做任何我想要的事情，以及享受相同的 Linux 体验。而且，如果我的系统出现问题，我可以使用 U 盘恢复！",-1)),n("p",null,[t[1]||(t[1]=i("创建单个",-1)),o(l,{href:"https://itsfoss.com/create-live-usb-of-ubuntu-in-windows/"},{default:s(()=>[...t[0]||(t[0]=[i("可启动的现场版 Linux USB",-1)])]),_:1}),t[2]||(t[2]=i(" 很简单，你只需下载一个 ISO 文件并将其刻录到 U 盘。但是，如果你想尝试多个 Linux 发行版呢？你可以使用多个 U 盘，也可以覆盖同一个 U 盘以尝试其他 Linux 发行版。但这两种方法都不是很方便。",-1))]),t[22]||(t[22]=u('<p>那么，有没有在单个 U 盘上安装多个 Linux 发行版的方式呢？我们将在本教程中看到如何做到这一点。</p><h3 id="如何创建有多个-linux-发行版的可启动-usb" tabindex="-1">如何创建有多个 Linux 发行版的可启动 USB <a class="header-anchor" href="#如何创建有多个-linux-发行版的可启动-usb" aria-label="Permalink to “如何创建有多个 Linux 发行版的可启动 USB”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2017/10/multiple-linux-on-one-usb-800x450.jpg" alt="How to install multiple linux distributions on a single USB"></p><p>我们有一个工具正好可以做到_在单个 U 盘上保留多个 Linux 发行版_。你所需要做的只是选择要安装的发行版。在本教程中，我们将介绍_如何在 U 盘中安装多个 Linux 发行版_用于<ruby>现场会话<rt>live session</rt></ruby>。</p><p>要确保你有一个足够大的 U 盘，以便在它上面安装多个 Linux 发行版，一个 8 GB 的 U 盘应该足够用于三四个 Linux 发行版。</p><h4 id="步骤-1" tabindex="-1">步骤 1 <a class="header-anchor" href="#步骤-1" aria-label="Permalink to “步骤 1”">​</a></h4>',6)),n("p",null,[o(l,{href:"http://multibootusb.org/"},{default:s(()=>[...t[3]||(t[3]=[i("MultiBootUSB",-1)])]),_:1}),t[4]||(t[4]=i(" 是一个自由、开源的跨平台应用程序，允许你创建具有多个 Linux 发行版的 U 盘。它还支持在任何时候卸载任何发行版，以便你回收驱动器上的空间用于另一个发行版。",-1))]),t[23]||(t[23]=n("p",null,"下载 .deb 包并双击安装。",-1)),n("p",null,[o(l,{href:"https://github.com/mbusb/multibootusb/releases/download/v8.8.0/python3-multibootusb_8.8.0-1_all.deb"},{default:s(()=>[...t[5]||(t[5]=[i("下载 MultiBootUSB",-1)])]),_:1})]),t[24]||(t[24]=u('<h4 id="步骤-2" tabindex="-1">步骤 2 <a class="header-anchor" href="#步骤-2" aria-label="Permalink to “步骤 2”">​</a></h4><p>推荐的文件系统是 FAT32，因此在创建多引导 U 盘之前，请确保格式化 U 盘。</p><h4 id="步骤-3" tabindex="-1">步骤 3 <a class="header-anchor" href="#步骤-3" aria-label="Permalink to “步骤 3”">​</a></h4><p>下载要安装的 Linux 发行版的 ISO 镜像。</p><h4 id="步骤-4" tabindex="-1">步骤 4 <a class="header-anchor" href="#步骤-4" aria-label="Permalink to “步骤 4”">​</a></h4><p>完成这些后，启动 MultiBootUSB。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/09/1.png" alt="MultiBootUSB"></p><p>主屏幕要求你选择 U 盘和你打算放到 U 盘上的 Linux 发行版镜像文件。</p><p>MultiBootUSB 支持 Ubuntu、Fedora 和 Debian 发行版的持久化，这意味着对 Linux 发行版的现场版本所做的更改将保存到 USB 上。</p><p>你可以通过拖动 MultiBootUSB 选项卡下的滑块来选择持久化大小。持久化为你提供了在运行时将更改保存到 U 盘的选项。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/09/2-1.png" alt="MultiBootUSB persistence storage"></p><h4 id="步骤-5" tabindex="-1">步骤 5 <a class="header-anchor" href="#步骤-5" aria-label="Permalink to “步骤 5”">​</a></h4><p>单击“安装发行版”选项并继续安装。在显示成功的安装消息之前，需要一些时间才能完成。</p><p>你现在可以在已安装部分中看到发行版了。对于另外的操作系统，重复该过程。这是我安装 Ubuntu 16.10 和 Fedora 24 后的样子。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/09/3.png" alt="MultiBootSystem with Ubuntu and Fedora"></p><h4 id="步骤-6" tabindex="-1">步骤 6 <a class="header-anchor" href="#步骤-6" aria-label="Permalink to “步骤 6”">​</a></h4><p>下次通过 USB 启动时，我可以选择任何一个发行版。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/09/VirtualBox_Ubuntu1610_23_09_2017_14_16_05-1.png" alt="Boot Menu"></p><p>只要你的 U 盘允许，你可以添加任意数量的发行版。要删除发行版，请从列表中选择它，然后单击卸载发行版。</p><h3 id="最后的话" tabindex="-1">最后的话 <a class="header-anchor" href="#最后的话" aria-label="Permalink to “最后的话”">​</a></h3><p>MultiBootUSB 真的很便于在 U 盘上安装多个 Linux 发行版。只需点击几下，我就有两个我最喜欢的操作系统的工作盘了，我可以在任何系统上启动它们。</p><p>如果你在安装或使用 MultiBootUSB 时遇到任何问题，请在评论中告诉我们。</p><hr>',23)),n("p",null,[t[7]||(t[7]=i("via: ",-1)),o(l,{href:"https://itsfoss.com/multiple-linux-one-usb/"},{default:s(()=>[...t[6]||(t[6]=[i("https://itsfoss.com/multiple-linux-one-usb/",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=i("作者：",-1)),o(l,{href:"https://itsfoss.com/author/ambarish/"},{default:s(()=>[...t[8]||(t[8]=[i("Ambarish Kumar",-1)])]),_:1}),t[12]||(t[12]=i(" 译者：",-1)),o(l,{href:"https://github.com/geekpi"},{default:s(()=>[...t[9]||(t[9]=[i("geekpi",-1)])]),_:1}),t[13]||(t[13]=i(" 校对：",-1)),o(l,{href:"https://github.com/wxy"},{default:s(()=>[...t[10]||(t[10]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=i("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[14]||(t[14]=[i("LCTT",-1)])]),_:1}),t[17]||(t[17]=i(" 原创编译，",-1)),o(l,{href:"https://linux.cn/"},{default:s(()=>[...t[15]||(t[15]=[i("Linux中国",-1)])]),_:1}),t[18]||(t[18]=i(" 荣誉推出",-1))])])}const T=e(d,[["render",x]]);export{S as __pageData,T as default};
